mapper.select:
SELECT id, name, base_url, api_key_cipher, api_key_last4 FROM model_provider
WHERE id = #{id}
ORDER BY id

mapper.update:
UPDATE model_provider
SET name = #{name}, base_url = #{baseUrl}, updated_at = now()
, api_key_cipher = #{apiKeyCipher}, api_key_last4 = #{apiKeyLast4}
WHERE id = #{id}

mapper.select:
SELECT id, purpose, before_provider_name, before_model, after_provider_id, after_provider_name, after_model,
       changed_by, changed_by_name, changed_at, restored_from
FROM model_change
WHERE id = #{id}
ORDER BY changed_at DESC, id DESC
LIMIT #{size} OFFSET #{offset}
